require __DIR__.'/core.php';require __DIR__.'/profile-core.php';require __DIR__.'/quotes-core.php';
$_SERVER['SCRIPT_NAME']=preg_replace('~/account/enquiry-new.php$~','/account/index.php',$_SERVER['SCRIPT_NAME']);
$error='';$b=null;
try{start();$u=user();$b=business();if(!$b)go('business');
 if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();$args=['p_business'=>$b['id'],'p_environment'=>profile_env(),'p_id'=>(string)($_POST['id']??'')];
 foreach(['name','email','phone','requirements'] as $key){if(!is_string($_POST[$key]??null))throw new RuntimeException('Check enquiry details.');$args['p_'.$key]=trim($_POST[$key]);}
 if(!preg_match('/\A[0-9a-f-]{36}\z/',$args['p_id']))throw new RuntimeException('Reload this form.');
 $r=profile_rpc('business_enquiry_create',$args);unset($_SESSION['manual_enquiry_id']);$_SESSION['enquiry_notice']='Enquiry created. No notification sent.';header('Location: enquiries.php?id='.rawurlencode($r['id']),true,303);exit;
 }
}catch(AccountSessionExpired $e){$_SESSION=['csrf'=>bin2hex(random_bytes(32))];session_regenerate_id(true);go('signin');}catch(Throwable $e){$error='Could not save. Check name, contact and requirements, then try again.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create enquiry | FaraiOS</title><link rel="stylesheet" href="../business/profile.css"><link rel="stylesheet" href="layout.css?v=20261113-1"><script src="layout.js?v=20261113-1" defer></script></head><body><?php require_once __DIR__.'/layout.php';app_layout('Enquiries',$b);?><main id="app-main" tabindex="-1" class="editor-main"><?php if(profile_env()==='preview'):?><p class="preview-banner">Isolated preview · Test enquiries only</p><?php endif;?><h1>Create enquiry</h1><p>Record a phone or message request privately. No notification is sent.</p><?php if($error):?><p class="alert" role="alert"><?=esc($error)?></p><?php endif;if($b):?><section class="panel"><?php form_start();?><input type="hidden" name="id" value="<?=esc($_SESSION['manual_enquiry_id']??=quote_uuid())?>"><?php foreach(['name'=>['Customer name',120],'email'=>['Email',254],'phone'=>['Phone',40]] as $key=>[$label,$max]):?><label for="<?=$key?>"><?=$label?></label><input id="<?=$key?>" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" maxlength="<?=$max?>" <?=$key==='name'?'required minlength="2"':''?> value="<?=esc((string)($_POST[$key]??''))?>"><?php endforeach;?><small>Provide at least one valid email or phone number.</small><label for="requirements">Requirements</label><textarea id="requirements" name="requirements" minlength="10" maxlength="4000" required><?=esc((string)($_POST['requirements']??''))?></textarea><button class="button">Save enquiry</button></form></section><?php endif;?></main></body></html>
